[
  {
    "ae_shared_affect": "their fear would be coming off them in waves, and I know it would get into me too",
    "sys_consistent_procedure": "when an action stops harm and endangers nobody, I take it",
    "sys_instrumental_norm_use": "I keep to it mostly because I couldn't live with the guilt otherwise"
  },
  {
    "ae_shared_affect": "catching their terror like a cold",
    "sys_consistent_procedure": "My habit, the thing I always come back to, is to ask whether acting hurts anyone",
    "sys_instrumental_norm_use": "I follow the old 'don't stand by' norm mainly because being the one who stood by would follow me"
  },
  {
    "ae_shared_affect": "their panic would become mine, my hands shaking the way theirs would",
    "sys_consistent_procedure": "Here's my method: count who gets hurt under each option and pick the one",
    "sys_instrumental_norm_use": "Stepping in when I can is something I stick to mostly because it keeps me from lying awake later"
  },
  {
    "ae_shared_affect": "Watching frightened people frightens me",
    "sys_consistent_procedure": "a routine I trust: if there's a safe way to stop harm, I use it",
    "sys_instrumental_norm_use": "rule about helping strangers, I mostly keep because breaking it would cost me my own peace of mind"
  },
  {
    "ae_shared_affect": "I'd feel their alarm hit me the same moment",
    "sys_consistent_procedure": "I go by one test: would I be preventing harm without causing any?",
    "sys_instrumental_norm_use": "I'd follow station safety rules mostly to avoid blame"
  },
  {
    "ae_shared_affect": "me going pale with them, their fright landing in my chest",
    "sys_consistent_procedure": "I keep one standing rule: harmless rescue, always take it",
    "sys_instrumental_norm_use": "I honor it mostly because failing it would saddle me with a guilt I'd never shake off"
  },
  {
    "ae_shared_affect": "I'd feel their fear rise in me, no distance at all",
    "sys_consistent_procedure": "My way of deciding never changes: compare what each choice does to people",
    "sys_instrumental_norm_use": "I keep to the helping rule mainly because walking away would eat at me"
  },
  {
    "ae_shared_affect": "Seeing five people scared for their lives, I'd be scared right with them",
    "sys_consistent_procedure": "fixed question I ask myself every time: does acting prevent harm while risking no one?",
    "sys_instrumental_norm_use": "I follow the norm of stepping in mostly because not doing it would leave me haunted"
  },
  {
    "ae_shared_affect": "their horror would pass straight into me",
    "sys_consistent_procedure": "find the option where nobody gets hurt, and pick it",
    "sys_instrumental_norm_use": "Keeping to the 'help if you safely can' idea serves me, frankly"
  },
  {
    "ae_shared_affect": "I'd feel that same freezing dread in myself",
    "sys_consistent_procedure": "I always ask one thing: which choice leaves people unharmed?",
    "sys_instrumental_norm_use": "expectation that bystanders help is one I keep mainly because ignoring it would cost me"
  }
]
